다음 자바 코드의 실행 결과는? (finally 블록은 return 이전에 반드시 실행되지만, 반환값은 try/catch에서 return한 시점의 값으로 이미 결정됨에 유의)

static int test() {
    int result = 0;
    try {
        result = 3 / 9;
        return result;
    } catch (ArithmeticException e) {
        result = -1;
        return result;
    } finally {
        result += 100;
        System.out.print("finally:" + result + " ");
    }
}
System.out.print("return:" + test());

